import { useRef, useState } from 'react';
import { Button, Linking, Text, View } from 'react-native';
import { CameraView, useCameraPermissions } from 'expo-camera';

export function CameraLesson({ onCaptured }: {
  onCaptured: (uri: string) => Promise<void>;
}) {
  const [permission, requestPermission] = useCameraPermissions();
  const camera = useRef<CameraView>(null);
  const inFlight = useRef(false);
  const [ready, setReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function capture() {
    if (!ready || inFlight.current || !camera.current) return;
    inFlight.current = true;
    setBusy(true);
    setError('');
    try {
      const image = await camera.current.takePictureAsync({ exif: false });
      if (!image) throw new Error('No photo was returned.');
      await onCaptured(image.uri);
    } catch {
      setError('The photo could not be captured. Please try again.');
    } finally {
      inFlight.current = false;
      setBusy(false);
    }
  }
  if (!permission) return <Text>Checking camera permission…</Text>;
  if (!permission.granted) {
    return <View style={{ gap: 12 }}>
      <Text>Use the camera to photograph a plant observation.</Text>
      <Button
        title={permission.canAskAgain ? 'Allow camera' : 'Open settings'}
        onPress={() => {
          void (permission.canAskAgain ? requestPermission() : Linking.openSettings());
        }} />
    </View>;
  }
  return <View style={{ gap: 12 }}>
    <CameraView ref={camera} style={{ height: 320 }}
      onCameraReady={() => setReady(true)} />
    <Button title={busy ? 'Preparing…' : 'Take photo'}
      disabled={!ready || busy} onPress={() => void capture()} />
    {error ? <Text accessibilityLiveRegion="polite">{error}</Text> : null}
  </View>;
}

import { randomUUID } from 'expo-crypto';
import { local, type Draft } from '../services/local';

export async function retainObservation(
  owner: string, uri: string, width: number, height: number,
): Promise<Draft> {
  const id = randomUUID();
  const original = await local.retain(owner, id, uri);
  const draft: Draft = {
    mode: 'plant', id, owner, observationId: randomUUID(), photoId: randomUUID(),
    capturedAt: new Date().toISOString(),
    original, width, height, derivative: null,
    nickname: '', place: '', text: '', ownership: 'observed',
    stage: 'draft', failure: null,
  };
  await local.save(draft);
  return draft;
}
